create or replace function public.listar_usuarios()returns jsonb language plpgsql stable security definer set search_path=''as $$declare result jsonb;begin if not public.has_permission('USUARIO_LEER')then raise exception using errcode='42501',message='No autorizado para consultar usuarios';end if;select coalesce(jsonb_agg(jsonb_build_object('id',u.id,'username',u.username,'fullName',u.nombre_completo,'email',u.email,'active',u.activo,'locked',u.bloqueado,'lastAccess',u.ultimo_acceso,'roles',coalesce((select jsonb_agg(r.codigo order by r.codigo)from public.usuarios_roles ur join public.roles r on r.id=ur.rol_id where ur.usuario_id=u.id),'[]'::jsonb))order by u.nombre_completo),'[]'::jsonb)into result from public.usuarios u;return result;end $$;
create or replace function public.listar_roles()returns jsonb language plpgsql stable security definer set search_path=''as $$declare result jsonb;begin if not public.has_permission('USUARIO_LEER')then raise exception using errcode='42501',message='No autorizado para consultar roles';end if;select coalesce(jsonb_agg(jsonb_build_object('code',r.codigo,'name',r.nombre,'description',r.descripcion,'permissions',coalesce((select jsonb_agg(p.codigo order by p.codigo)from public.roles_permisos rp join public.permisos p on p.id=rp.permiso_id where rp.rol_id=r.id),'[]'::jsonb))order by r.nombre),'[]'::jsonb)into result from public.roles r where r.activo;return result;end $$;
create or replace function public.cambiar_estado_usuario(usuario_id bigint,nuevo_activo boolean)returns jsonb language plpgsql security definer set search_path=''as $$declare actor bigint:=public.current_app_user_id();result jsonb;begin if actor is null or not public.has_permission('USUARIO_ESCRIBIR')then raise exception using errcode='42501',message='No autorizado para modificar usuarios';end if;if actor=usuario_id and not nuevo_activo then raise exception using errcode='P0001',message='No puede desactivar su propio usuario';end if;update public.usuarios set activo=nuevo_activo,actualizado_en=now()where id=usuario_id;if not found then raise exception using errcode='P0001',message='Usuario no encontrado';end if;perform public.registrar_auditoria(case when nuevo_activo then'ACTIVAR_USUARIO'else'DESACTIVAR_USUARIO'end,'USUARIO',usuario_id::text,null);select jsonb_build_object('id',u.id,'username',u.username,'fullName',u.nombre_completo,'email',u.email,'active',u.activo,'locked',u.bloqueado,'lastAccess',u.ultimo_acceso,'roles',coalesce((select jsonb_agg(r.codigo order by r.codigo)from public.usuarios_roles ur join public.roles r on r.id=ur.rol_id where ur.usuario_id=u.id),'[]'::jsonb))into result from public.usuarios u where u.id=usuario_id;return result;end $$;
create or replace function public.listar_configuracion()returns jsonb language plpgsql stable security definer set search_path=''as $$declare result jsonb;begin if not public.has_permission('USUARIO_LEER')then raise exception using errcode='42501',message='No autorizado para consultar configuración';end if;select coalesce(jsonb_agg(jsonb_build_object('key',c.clave,'value',c.valor,'description',c.descripcion,'updatedBy',c.actualizado_por,'updatedAt',c.actualizado_en,'version',c.version)order by c.clave),'[]'::jsonb)into result from public.configuracion_sistema c;return result;end $$;
create or replace function public.actualizar_configuracion(clave text,valor text,version_actual bigint)returns jsonb language plpgsql security definer set search_path=''as $$declare actor bigint:=public.current_app_user_id();item public.configuracion_sistema;begin if actor is null or not public.has_permission('AJUSTE_ESCRIBIR')then raise exception using errcode='42501',message='No autorizado para modificar configuración';end if;update public.configuracion_sistema set valor=btrim(valor),actualizado_por=actor,actualizado_en=now(),version=version+1 where configuracion_sistema.clave=actualizar_configuracion.clave and version=version_actual returning*into item;if not found then raise exception using errcode='P0001',message='La configuración fue modificada o no existe';end if;perform public.registrar_auditoria('ACTUALIZAR_CONFIGURACION','CONFIGURACION',clave,'Parámetro actualizado');return jsonb_build_object('key',item.clave,'value',item.valor,'description',item.descripcion,'updatedBy',item.actualizado_por,'updatedAt',item.actualizado_en,'version',item.version);end $$;
create or replace function public.consultar_auditoria(desde timestamptz,hasta timestamptz,busqueda text default null,pagina integer default 0,tamano integer default 50)returns jsonb language plpgsql stable security definer set search_path=''as $$declare result jsonb;total bigint;safe_size integer:=least(greatest(tamano,1),100);safe_page integer:=greatest(pagina,0);begin if not public.has_permission('AUDITORIA_LEER')then raise exception using errcode='42501',message='No autorizado para consultar auditoría';end if;if hasta<=desde or hasta-desde>interval'367 days'then raise exception using errcode='P0001',message='Rango de consulta inválido';end if;select count(*)into total from public.auditoria a where a.creado_en between desde and hasta and(nullif(btrim(busqueda),'')is null or concat_ws(' ',a.username,a.accion,a.recurso,a.recurso_id,a.detalle)ilike'%'||btrim(busqueda)||'%');select jsonb_build_object('content',coalesce(jsonb_agg(x.data),'[]'::jsonb),'totalElements',total,'totalPages',ceil(total::numeric/safe_size)::integer,'number',safe_page,'size',safe_size)into result from(select jsonb_build_object('id',a.id,'userId',a.usuario_id,'username',a.username,'action',a.accion,'resource',a.recurso,'resourceId',a.recurso_id,'result',a.resultado,'ip',a.ip,'detail',a.detalle,'createdAt',a.creado_en)data from public.auditoria a where a.creado_en between desde and hasta and(nullif(btrim(busqueda),'')is null or concat_ws(' ',a.username,a.accion,a.recurso,a.recurso_id,a.detalle)ilike'%'||btrim(busqueda)||'%')order by a.creado_en desc offset safe_page*safe_size limit safe_size)x;return result;end $$;
create or replace function public.resumen_operacional(desde timestamptz,hasta timestamptz)returns jsonb language plpgsql stable security definer set search_path=''as $$declare finance jsonb;begin if not public.has_permission('AUDITORIA_LEER')then raise exception using errcode='42501',message='No autorizado para consultar resumen';end if;finance:=public.resumen_finanzas(desde,hasta);return jsonb_build_object('patients',(select count(*)from public.pacientes),'appointments',(select count(*)from public.citas where inicio between desde and hasta),'confirmedAppointments',(select count(*)from public.citas where inicio between desde and hasta and estado='CONFIRMADA'),'completedEncounters',(select count(*)from public.atenciones_clinicas where fecha_atencion between desde and hasta and estado='FINALIZADA'),'income',finance->'income','expenses',finance->'expenses','net',finance->'net','receivables',finance->'receivable','followUpAlerts',(select count(*)from public.seguimientos_postconsulta where estado='ALERTA'),'failedMessages',(select count(*)from public.mensajes_whatsapp where estado='FALLIDO'and creado_en between desde and hasta),'from',desde,'to',hasta);end $$;

revoke all on function public.listar_usuarios(),public.listar_roles(),public.cambiar_estado_usuario(bigint,boolean),public.listar_configuracion(),public.actualizar_configuracion(text,text,bigint),public.consultar_auditoria(timestamptz,timestamptz,text,integer,integer),public.resumen_operacional(timestamptz,timestamptz)from public;
grant execute on function public.listar_usuarios(),public.listar_roles(),public.cambiar_estado_usuario(bigint,boolean),public.listar_configuracion(),public.actualizar_configuracion(text,text,bigint),public.consultar_auditoria(timestamptz,timestamptz,text,integer,integer),public.resumen_operacional(timestamptz,timestamptz)to authenticated;
